const CFG = {
  AI_THRESHOLD: 40,
  HIGH_THRESHOLD: 65,
  WATCH_THRESHOLD: 20,
  MIN_BASELINE_BUCKETS: 3,
  MIN_BASELINE_AVG_ORDERS: 1,
  BLACKOUT_DAMPEN_DAYS: 7,
  BLACKOUT_FACTOR: 0.75,
  ESCALATION_DELTA: 15,
};

const num = (v, d = 0) => (v === null || v === undefined || v === '' || Number.isNaN(Number(v))) ? d : Number(v);
const nz  = (v) => (v === null || v === undefined || v === '') ? null : Number(v);
const results = [];

for (const item of $input.all()) {
  const r = item.json;
  const signals = [], dampeners = [], dataGaps = [];
  const add = (id, category, points, max, detail) => {
    if (points > 0) signals.push({ id, category, points, max, detail });
  };

  const buckets = num(r.baseline_buckets);
  const baseOrders = num(r.baseline_avg_orders);
  const baselineOK = buckets >= CFG.MIN_BASELINE_BUCKETS && baseOrders >= CFG.MIN_BASELINE_AVG_ORDERS;
  const seasonal = num(r.seasonal_ratio, 1) || 1;
  const cycleFactor = r.billing_cycle === 'monthly' ? 1 : 0.5;
  const blackout = num(r.blackout_days_recent);
  const ordersRecent = num(r.orders_recent);
  const spendRecent = num(r.spend_recent);

  if (buckets < CFG.MIN_BASELINE_BUCKETS) dataGaps.push(`Only ${buckets} month(s) of own order history — purchasing-pattern signals not evaluated`);
  else if (baseOrders < CFG.MIN_BASELINE_AVG_ORDERS) dataGaps.push('Low-frequency buyer (<1 order per 30 days) — monthly purchasing-pattern signals not evaluated');
  if (r.last_meaningful_contact_at === null) dataGaps.push('No meaningful two-way contact on record');
  if (!r.crm_record_id) dataGaps.push('No CRM record id — CRM update/task will be skipped');
  if (!r.am_id) dataGaps.push('No account manager assigned');

  const expectedOrders = baseOrders * seasonal;
  const expectedSpend = num(r.baseline_avg_spend) * seasonal;
  const orderRatio = baselineOK && expectedOrders > 0 ? ordersRecent / expectedOrders : null;
  const spendRatio = baselineOK && expectedSpend > 0 ? spendRecent / expectedSpend : null;

  if (orderRatio !== null) {
    let pts = orderRatio <= 0.25 ? 30 : orderRatio <= 0.5 ? 22 : orderRatio <= 0.75 ? 12 : 0;
    const sd = num(r.baseline_sd_orders);
    const z = sd > 0 ? (expectedOrders - ordersRecent) / sd : null;
    let note = '';
    if (pts > 0 && z !== null && z < 1 && z >= 0) {
      pts = Math.round(pts * 0.5);
      note = ' (within normal month-to-month variation, halved)';
    }
    pts = Math.round(pts * cycleFactor);
    add('order_frequency', 'purchasing', pts, 30,
      `${ordersRecent} orders in last 30d vs ~${expectedOrders.toFixed(1)} expected (own 6-mo avg ${baseOrders.toFixed(1)} per 30d × seasonal ${seasonal.toFixed(2)})${note}`);
  }

  if (spendRatio !== null) {
    let pts = spendRatio <= 0.4 ? 20 : spendRatio <= 0.6 ? 14 : spendRatio <= 0.8 ? 7 : 0;
    pts = Math.round(pts * cycleFactor);
    add('spend_change', 'purchasing', pts, 20,
      `Spend ${Math.round(spendRecent)} in last 30d vs ~${Math.round(expectedSpend)} expected (${Math.round(spendRatio * 100)}% of own norm)`);
  }

  const gap = nz(r.typical_order_gap_days), dslo = nz(r.days_since_last_order);
  if (baselineOK && gap && gap > 0 && dslo !== null) {
    const effGap = gap / Math.max(seasonal, 0.25);
    const overdue = dslo / effGap;
    let pts = overdue >= 3 ? 10 : overdue >= 2 ? 6 : overdue >= 1.5 ? 3 : 0;
    pts = Math.round(pts * cycleFactor);
    add('order_overdue', 'purchasing', pts, 10,
      `${dslo} days since last order vs typical ${gap.toFixed(1)}-day rhythm (${overdue.toFixed(1)}x)`);
  }

  const dsc = nz(r.days_since_meaningful_contact);
  const unans = num(r.unanswered_outbound);
  if (dsc !== null) {
    const p = dsc >= 30 ? 12 : dsc >= 20 ? 9 : dsc >= 14 ? 5 : 0;
    add('contact_silence', 'engagement', p, 12, `${dsc} days since last meaningful two-way contact`);
  }
  add('unanswered_outreach', 'engagement', unans >= 3 ? 8 : unans === 2 ? 5 : unans === 1 ? 2 : 0, 8,
    `${unans} outbound message(s) from the account team unanswered since last meaningful contact`);
  const cb = num(r.contacts_baseline_avg_30d), cr = num(r.contacts_recent_30d);
  if (cb >= 2 && cr <= cb * 0.25) add('contact_frequency_drop', 'engagement', 4, 4, `${cr} two-way contacts in last 30d vs ${cb.toFixed(1)} per 30d normally`);

  const od = nz(r.oldest_open_ticket_days);
  if (num(r.open_tickets) > 0 && od !== null) {
    add('open_ticket_age', 'support', od >= 14 ? 8 : od >= 7 ? 5 : od >= 3 ? 2 : 0, 8,
      `${num(r.open_tickets)} open ticket(s); oldest unresolved ${od} days`);
  }
  add('high_priority_open', 'support', num(r.open_high_priority_tickets) > 0 ? 4 : 0, 4, `${num(r.open_high_priority_tickets)} open high/urgent ticket(s)`);
  add('negative_tickets', 'support', num(r.negative_tickets_30d) >= 2 ? 3 : 0, 3, `${num(r.negative_tickets_30d)} negative-sentiment tickets in last 30d`);

  const dsm = nz(r.days_since_meeting);
  if (dsm !== null) add('no_recent_meeting', 'relationship', dsm >= 90 ? 5 : dsm >= 60 ? 3 : 0, 5, `${dsm} days since last meeting`);

  if (blackout >= CFG.BLACKOUT_DAMPEN_DAYS) {
    for (const s of signals) {
      if (s.category === 'purchasing' || s.category === 'engagement') s.points = Math.round(s.points * CFG.BLACKOUT_FACTOR);
    }
    dampeners.push(`${blackout} of the last 30 days fall in a holiday/closure window — purchasing & engagement points reduced 25%`);
  }
  if (Math.abs(seasonal - 1) >= 0.15) dampeners.push(`Seasonality applied: current period expected at ${Math.round(seasonal * 100)}% of the baseline period for segment "${r.segment}"`);
  if (r.billing_cycle !== 'monthly') dampeners.push(`${r.billing_cycle} billing cycle — order-based signals weighted 50%`);

  const live = signals.filter(s => s.points > 0);
  let score = Math.min(100, live.reduce((a, s) => a + s.points, 0));
  const categories = new Set(live.filter(s => s.points >= 5).map(s => s.category));

  let level = score >= CFG.HIGH_THRESHOLD ? 'high' : score >= CFG.AI_THRESHOLD ? 'medium' : score >= CFG.WATCH_THRESHOLD ? 'watch' : 'healthy';
  if (level === 'high' && categories.size < 2) { level = 'medium'; dampeners.push('Capped at MEDIUM: only one evidence category (needs corroboration from a second category for HIGH)'); }
  if (!baselineOK && level === 'high') { level = 'medium'; dampeners.push('Capped at MEDIUM: insufficient order baseline'); }

  let suppressed_reason = null;
  if (r.planned_pause_active) suppressed_reason = 'Customer announced a planned pause';
  else if (r.snoozed) suppressed_reason = `Snoozed by account manager${r.snooze_reason ? ': ' + r.snooze_reason : ''}`;
  if (suppressed_reason) level = 'suppressed';

  const lastScore = nz(r.last_risk_score);
  const escalated = (level === 'high' && r.last_risk_level !== 'high') || (lastScore !== null && score - lastScore >= CFG.ESCALATION_DELTA);
  const inCooldown = !!r.has_open_followup && !escalated;
  if (!suppressed_reason && score >= CFG.AI_THRESHOLD && inCooldown) suppressed_reason = 'Follow-up already open for this account (no material escalation)';

  const send_to_ai = !suppressed_reason && score >= CFG.AI_THRESHOLD;

  const metrics = {
    orders_recent: ordersRecent, orders_expected: +expectedOrders.toFixed(2), order_ratio: orderRatio === null ? null : +orderRatio.toFixed(2),
    spend_recent: spendRecent, spend_expected: Math.round(expectedSpend), spend_ratio: spendRatio === null ? null : +spendRatio.toFixed(2),
    baseline_avg_orders: baseOrders, baseline_buckets: buckets, seasonal_ratio: seasonal,
    days_since_last_order: dslo, typical_order_gap_days: gap,
    days_since_meaningful_contact: dsc, unanswered_outbound: unans, days_since_meeting: dsm,
    open_tickets: num(r.open_tickets), oldest_open_ticket_days: od, blackout_days_recent: blackout,
    billing_cycle: r.billing_cycle, last_risk_score: lastScore,
  };

  results.push({ json: {
    customer_id: r.customer_id, company_name: r.company_name, crm_record_id: r.crm_record_id,
    am: { id: r.am_id, name: r.am_name, email: r.am_email, slack_user_id: r.am_slack_user_id, hubspot_owner_id: r.am_hubspot_owner_id },
    risk_score: score, risk_level: level, signals: live, dampeners, data_gaps: dataGaps, metrics,
    send_to_ai, suppressed_reason,
    evidence: {
      customer: { id: r.customer_id, name: r.company_name, segment: r.segment, billing_cycle: r.billing_cycle, tenure_days: num(r.tenure_days) },
      screening_result: { score, level, ai_threshold: CFG.AI_THRESHOLD, note: 'Rule-based screening score, not a churn prediction' },
      signals: live, dampeners, data_gaps: dataGaps, metrics,
    },
  } });
}

results.sort((a, b) => b.json.risk_score - a.json.risk_score);
return results;

const base = $('Check AI Analysis Need').item.json;
return {
  json: {
    ...base,
    evidence: {
      ...base.evidence,
      recent_tickets: $json.recent_tickets || [],
      recent_communications:$json.recent_comms || []
    }
  }
};

const assembleItems = $('Build Evidence Payload').all();
const currentIdx = $itemIndex;
const src = (assembleItems[currentIdx] && assembleItems[currentIdx].json) || {};
const ai =$json.output;

const validIds = new Set((src.signals || []).map(s => s.id));
const clean = (arr) => (Array.isArray(arr) ? arr : []).filter(x => x && validIds.has(x.signal_id));

let diagnosis = null, ai_error = null;
if (!ai || typeof ai !== 'object') {
  ai_error = 'AI returned no structured output';
} else {
  const cleanedEvidence = clean(ai.supporting_evidence);
  diagnosis = {
    ...ai,
    what_changed: clean(ai.what_changed),
    supporting_evidence: cleanedEvidence,
    requires_human_review: true
  };
  if (cleanedEvidence.length === 0 && (src.signals || []).length > 0) {
    ai_error = 'AI diagnosis cited no validated rule signal IDs; flagged for manual review';
  }
}
return { json: { ...src, ai_diagnosis: diagnosis, ai_error } };

const r = $json;
const d = r.ai_diagnosis || null;
const urgency = d?.recommended_action?.urgency || (r.risk_level === 'high' ? 'today' : 'this_week');
const addDays = { today: 0, this_week: 3, next_week: 7 }[urgency] ?? 3;

// Precise Asia/Kolkata date construction
const now = new Date();
const kolkataNow = new Date(now.getTime() + (330 + now.getTimezoneOffset()) * 60000);
kolkataNow.setDate(kolkataNow.getDate() + addDays);
const due_date = kolkataNow.toISOString().slice(0, 10);

const actionable = r.send_to_ai === true && ['medium', 'high'].includes(r.risk_level);
const topSignals = (r.signals || []).slice().sort((a, b) => b.points - a.points).slice(0, 4);

const recommended_action_text = actionable 
  ? (d?.recommended_action?.action || 'AI diagnosis unavailable — review the account manually and reach out personally; see top signals.')
  : null;

const summary = d?.summary || (actionable ? 'Automated screening flagged behavioural drift vs this customer\'s baseline. AI diagnosis unavailable.' : null);

const taskBodyParts = [
  `[Drift ${r.risk_level.toUpperCase()} · score ${r.risk_score}/100] ${r.company_name}`,
  summary,
  '',
  'What changed:',
  ...(d?.what_changed?.length ? d.what_changed.map(w => '- ' + w.observation) : topSignals.map(s => '- ' + s.detail)),
  ''
];

if (d?.likely_reason) {
  taskBodyParts.push(`Likely reason (hypothesis, ${d.likely_reason.confidence} confidence): ${d.likely_reason.hypothesis}`);
}
if (d?.false_alarm_check?.assessment) {
  taskBodyParts.push(`False-alarm check: ${d.false_alarm_check.assessment}`);
}
if (recommended_action_text) {
  taskBodyParts.push(`Suggested next step (${urgency}): ${recommended_action_text}`);
}
if (d?.recommended_action?.talking_points?.length) {
  taskBodyParts.push('Talking points:');
  taskBodyParts.push(...d.recommended_action.talking_points.map(t => '- ' + t));
}
taskBodyParts.push('', 'Screening signal + AI summary built from CRM/order/ticket data. You decide whether and how to contact the customer.');

const taskBody = taskBodyParts.filter(x => x !== null && x !== undefined).join('\n');

const crm_company_payload = {
  properties: {
    drift_risk_score: r.risk_score,
    drift_risk_level: r.risk_level,
    drift_diagnosis: (summary || '').slice(0, 5000),
    drift_recommended_action: (recommended_action_text || '').slice(0, 2000),
    drift_last_assessed: new Date().toISOString().slice(0, 10),
  }
};

const crm_task_payload = {
  properties: {
    hs_timestamp: new Date(`${due_date}T09:00:00+05:30`).toISOString(),
    hs_task_subject: `${r.risk_level === 'high' ? '🔴 ' : '🟠 '}Retention check-in: ${r.company_name} (drift ${r.risk_score}/100)`,
    hs_task_body: taskBody,
    hs_task_priority: r.risk_level === 'high' ? 'HIGH' : 'MEDIUM',
    hs_task_status: 'NOT_STARTED',
    hs_task_type: 'CALL',
    ...(r.am?.hubspot_owner_id ? { hubspot_owner_id: String(r.am.hubspot_owner_id) } : {}),
  },
  associations: [{ to: { id: r.crm_record_id }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 192 }] }],
};

const emoji = r.risk_level === 'high' ? '🔴' : '🟠';
const mention = r.am?.slack_user_id ? `<@${r.am.slack_user_id}>` : (r.am?.name || 'Account manager');
const slackParts = [
  `${emoji} *Drift alert — ${r.company_name}* (${r.risk_level.toUpperCase()}, score ${r.risk_score}/100)`,
  summary,
  '*What changed:*',
  ...topSignals.map(s => '• ' + s.detail),
];
if (d?.likely_reason) {
  slackParts.push(`*Likely reason (hypothesis, ${d.likely_reason.confidence} confidence):* ${d.likely_reason.hypothesis}`);
}
if (recommended_action_text) {
  slackParts.push(`*Suggested next step (${urgency}):* ${recommended_action_text}`);
}
slackParts.push(`${mention} — CRM task created, due ${due_date}. _Screening signal, not a verdict — you decide whether to reach out._`);

const slack_text = slackParts.filter(Boolean).join('\n');

return { 
  json: { 
    ...r, 
    urgency, 
    due_date, 
    actionable, 
    diagnosis_summary: summary, 
    recommended_action_text, 
    crm_company_payload, 
    crm_task_payload, 
    slack_text 
  } 
};
